{"predictors": [
  {
    "name": "Net Working Capital Ratio", 
    "construction": "Calculated by subtracting current liabilities from current assets and dividing by total assets. Data source: quarterly balance sheets.", 
    "rationale": "Companies with higher net working capital ratios may be better able to weather financial distress.", 
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "CEO Tenure", 
    "construction": "Number of years the current CEO has held the position. Data source: annual proxy statements.", 
    "rationale": "CEOs with longer tenure may have more experience and knowledge, leading to better performance.", 
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Sales Volatility", 
    "construction": "Standard deviation of past 5 years' quarterly sales growth rates. Data source: quarterly income statements.", 
    "rationale": "Firms with more stable sales may be more predictable and less risky.", 
    "higher_returns_for": "Low values of the measure"
  },
  {
    "name": "Capital Expenditure Ratio", 
    "construction": "Capital expenditures divided by net income, averaged over the past 5 years. Data source: annual cash flow statements.", 
    "rationale": "Firms that invest more in capital may be anticipating growth.", 
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Employee Efficiency", 
    "construction": "Revenue divided by number of employees. Data source: annual income statements and Form 10-K disclosures.", 
    "rationale": "Firms that generate more revenue per employee may be more efficient or have more valuable human capital.", 
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Dividend Change", 
    "construction": "Change in dividends per share over the past year. Data source: annual dividend announcements.", 
    "rationale": "A recent increase in dividends may signal confidence from management.", 
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Share Repurchase Ratio", 
    "construction": "Dollar amount of share repurchases divided by market capitalization. Data source: annual cash flow statements and stock price data.", 
    "rationale": "Companies repurchasing their own shares may expect their stock price to rise.", 
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Debt Maturity", 
    "construction": "Weighted average maturity of the firm's debt. Data source: annual financial statement footnotes.", 
    "rationale": "Longer debt maturity may reduce refinancing risk and signal creditworthiness.", 
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Pension Fund Status", 
    "construction": "Funded status of the firm's pension plan, defined as the difference between plan assets and projected obligations. Data source: annual pension plan disclosures.", 
    "rationale": "Better-funded pension plans may reduce future corporate financial risk.", 
    "higher_returns_for": "High values of the measure"
  },
  {
    "name": "Customer Concentration", 
    "construction": "Revenue from the firm's largest customer divided by total revenue. Data source: annual Form 10-K disclosures.", 
    "rationale": "Higher customer concentration may increase business risk due to dependence on a single customer.", 
    "higher_returns_for": "Low values of the measure"
  }
]}
